"""PreToolUse hook: block hand edits to files generated by scripts/build_site.py."""

import json
import sys

GENERATED = ("site/tools-reference.json",)

data = json.load(sys.stdin)
path = ((data.get("tool_input") or {}).get("file_path") or "").replace("\\", "/")
if any(path.endswith(g) for g in GENERATED):
    print(
        f"{path} is generated. Change the tool registry/descriptions and run `python scripts/build_site.py` instead.",
        file=sys.stderr,
    )
    sys.exit(2)
